import{_ as a,o as t,c as n,a0 as s}from"./chunks/framework.BQGW-Zpy.js";const m=JSON.parse('{"title":"System Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md"}'),r={name:"architecture/overview.md"};function i(o,e,l,c,p,h){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="system-overview" tabindex="-1">System Overview <a class="header-anchor" href="#system-overview" aria-label="Permalink to &quot;System Overview&quot;">​</a></h1><p>The system separates two concerns that are easy to conflate, and keeping them separate is the central architectural decision of the whole project:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Question it answers</th><th>Always</th></tr></thead><tbody><tr><td><strong>Trust layer</strong> (<a href="./trust-layer.html">Hedera</a>)</td><td>Did this check happen, and when?</td><td>Hedera</td></tr><tr><td><strong>Settlement layer</strong> (<a href="./settlement-layer.html">routing</a>)</td><td>Which chain actually moved the value?</td><td>Chosen per transfer</td></tr></tbody></table><h2 id="why-they-re-separate" tabindex="-1">Why they&#39;re separate <a class="header-anchor" href="#why-they-re-separate" aria-label="Permalink to &quot;Why they&#39;re separate&quot;">​</a></h2><p>A product&#39;s trust anchor and its settlement rail don&#39;t have to be the same network. Hedera Consensus Service gives us a fixed-fee, deterministic-finality timestamping service, ideal for a compliance trail that has to remain economical and verifiable for years. But Hedera&#39;s own stablecoin liquidity is real yet thin (tens of millions of dollars, not billions), so a large transfer settled entirely on Hedera could see meaningful slippage.</p><p>Separating the two means: <strong>the compliance and routing evidence is always anchored the same way, on the same network, regardless of which chain the money actually moves through.</strong> A regulator examining a transfer years later doesn&#39;t need to trust whichever settlement chain was in fashion at the time, only the anchor, which never changes.</p><h2 id="component-map" tabindex="-1">Component map <a class="header-anchor" href="#component-map" aria-label="Permalink to &quot;Component map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>backend/services/hedera/, the trust anchor, always Hedera</span></span>
<span class="line"><span>  client.mjs        Hedera connection + key parsing</span></span>
<span class="line"><span>  hashing.mjs        canonical hashing + HMAC pseudonymous refs</span></span>
<span class="line"><span>  topic.mjs           HCS topic creation/reuse</span></span>
<span class="line"><span>  anchor.mjs           compliance / quote / routing-decision anchoring</span></span>
<span class="line"><span>  verify.mjs            Mirror Node read-back + tamper detection</span></span>
<span class="line"><span></span></span>
<span class="line"><span>backend/services/settlement/, which chain moves the value</span></span>
<span class="line"><span>  corridorConfig.mjs   partner chain support, compliant stablecoins</span></span>
<span class="line"><span>  liquidity.mjs         real Hedera liquidity depth (DeFiLlama)</span></span>
<span class="line"><span>  corridorRouter.mjs     the routing decision function</span></span>
<span class="line"><span>  execute.mjs             real execution (Hedera) / labeled non-execution (elsewhere)</span></span></code></pre></div><p>Full function-level detail: <a href="./../reference/modules.html">Module Reference</a>.</p>`,9)])])}const u=a(r,[["render",i]]);export{m as __pageData,u as default};
